// 原成功Training永久载荷的原因/实际ActorMutation投影门，无完整condition或World验收声明。
#include "resident/domains/growth/growth_training_condition_source.hpp"
#include "resident/domains/growth/growth_model.hpp"
#include "resident/model/common_model.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {Integer checks=0;void check(bool v,const char* s){++checks;if(!v)throw std::runtime_error(s);}}
int main(){try{
 CommonState c;c.identity.tick=2;c.next_instance_id=99;ActorRecord student;student.id="student";student.fatigue=12;c.actors.insert(student.id,student);ActorRecord teacher;teacher.id="teacher";teacher.fatigue=17;c.actors.insert(teacher.id,teacher);GrowthState g;
 TrainingFact f;f.phase="completed";f.action_kind="learn_skill";f.actor_id="student";f.start_tick=0;f.completed_tick=2;f.success=true;f.training.student_id="student";f.training.teacher_id="teacher";f.training.duration=2;f.training.student_fatigue=8;f.training.teacher_fatigue=4;g.facts.insert("action:10",f);c.facts.insert("action:10",{"action:10","training","cultivation"});
 auto source=read_growth_training_condition_cause(c,g,"action:10");check(source.ok&&source.value.actor_ids==std::vector<StableId>{"student","teacher"},"actual student and teacher order");check(source.value.business.effective_tick==2&&source.value.business.ordinal==1&&source.value.actual_completion_id.empty(),"actual completion tick without invented head");
 std::vector<GrowthPersonalConditionActorEffect> effects{{"student",{{},4},{{},12}},{"teacher",{{},13},{{},17}}};check(validate_growth_training_condition_effects(c,g,source.value,effects).ok,"original student eight teacher four");
 c.actors.find("student")->fatigue=92;check(validate_growth_training_condition_effects(c,g,source.value,effects).ok,"today fatigue not used as historical before");effects[0].before.fatigue=99;effects[0].after.fatigue=100;check(validate_growth_training_condition_effects(c,g,source.value,effects).ok,"original capped actual fatigue");effects[0].before.fatigue=100;check(validate_growth_training_condition_effects(c,g,source.value,effects).ok,"saturated write still present");effects[0].after.fatigue.reset();check(!validate_growth_training_condition_effects(c,g,source.value,effects).ok,"missing saturated write not omitted");effects[0].after.fatigue=100;effects[0].after.hp=100;check(!validate_growth_training_condition_effects(c,g,source.value,effects).ok,"Training cannot authorize hp write");effects[0].after.hp.reset();std::swap(effects[0],effects[1]);check(!validate_growth_training_condition_effects(c,g,source.value,effects).ok,"actual actor order cannot be swapped");std::swap(effects[0],effects[1]);
 auto forged=source.value;forged.business.effective_tick=1;check(!validate_growth_training_condition_effects(c,g,forged,effects).ok,"self-stored tick cannot replace original completion");forged=source.value;forged.business.ordinal=2;check(!validate_growth_training_condition_effects(c,g,forged,effects).ok,"no invented second completion");forged=source.value;forged.actual_completion_id="result:20";check(!validate_growth_training_condition_effects(c,g,forged,effects).ok,"no fake result for original Training");
 auto ids=read_growth_training_condition_cause_ids(c,g);check(ids.ok&&ids.value==std::vector<StableId>{"action:10"},"reverse enumeration from original ledger");c.facts.insert("action:20",{"action:20","training","cultivation"});check(!read_growth_training_condition_cause_ids(c,g).ok,"header missing payload rejected");c.facts.erase("action:20");
 auto* tf=std::get_if<TrainingFact>(g.facts.find("action:10"));tf->success=false;check(!read_growth_training_condition_cause(c,g,"action:10").ok&&read_growth_training_condition_cause_ids(c,g).value.empty(),"failed training has no actual fatigue write");tf->success=true;
 c.identity.tick=1;check(!read_growth_training_condition_cause(c,g,"action:10").ok,"stable cannot read future completion");DynamicStepInput phase;phase.from_tick=1;phase.to_tick=2;check(!read_growth_training_condition_cause(c,g,"action:10",&phase).ok,"future completed action must belong to actual phase prefix");phase.existing_action_ids={"action:10"};auto future=read_growth_training_condition_cause(c,g,"action:10",&phase);check(future.ok&&future.value.source_identity.tick==1&&future.value.business.effective_tick==2,"strict actual actions step observes to before clock");check(validate_growth_training_condition_effects(c,g,future.value,effects,&phase).ok,"matching phase effects verified");phase.from_tick=0;check(!read_growth_training_condition_cause(c,g,"action:10",&phase).ok,"wrong phase rejected");phase.from_tick=1;phase.to_tick=3;check(!read_growth_training_condition_cause(c,g,"action:10",&phase).ok,"multi step future rejected");
 c.identity.tick=2;tf->training.student_fatigue=9;check(!read_growth_training_condition_cause(c,g,"action:10").ok,"frozen delta cannot exceed original rule");tf->training.student_fatigue=8;tf->completed_tick=3;check(!read_growth_training_condition_cause(c,g,"action:10").ok,"original duration bounds completion");tf->completed_tick=2;c.facts.find("action:10")->domain="services";check(!read_growth_training_condition_cause(c,g,"action:10").ok,"wrong domain rejected");
 std::cout<<"GROWTH_TRAINING_CONDITION_SOURCE "<<checks<<" checks 0 failures\n";return 0;
}catch(const std::exception& e){std::cerr<<"GROWTH_TRAINING_CONDITION_SOURCE "<<checks<<" checks 1 failure: "<<e.what()<<'\n';return 1;}}
